import express, { NextFunction, Request, Response } from "express";
import client from "prom-client";

const register = new client.Registry();
client.collectDefaultMetrics({ register });

const httpRequestsTotal = new client.Counter({
  name: "http_requests_total",
  help: "Total number of HTTP requests",
  labelNames: ["method", "route", "status_code"] as const,
  registers: [register],
});

const httpRequestDuration = new client.Histogram({
  name: "http_request_duration_seconds",
  help: "HTTP request duration in seconds (feeds the p95 Grafana panel)",
  labelNames: ["method", "route", "status_code"] as const,
  buckets: [0.01, 0.05, 0.1, 0.3, 0.5, 1, 2, 5],
  registers: [register],
});

/**
 * Wired BEFORE the route handler and validation middleware.
 */
function metricsMiddleware(req: Request, res: Response, next: NextFunction): void {
  const start = Date.now();

  // Reads and records immediately, at entry -- before next() runs
  // the handler and validation.
  const statusCode = res.statusCode; // still the default 200 here
  const durationSeconds = (Date.now() - start) / 1000; // ~0, no handler work has run yet

  httpRequestsTotal.inc({
    method: req.method,
    route: req.path,
    status_code: statusCode,
  });
  httpRequestDuration.observe(
    { method: req.method, route: req.path, status_code: statusCode },
    durationSeconds,
  );

  next();
}

function validateCreateOrder(req: Request, res: Response, next: NextFunction): void {
  const { amount } = req.body as { amount?: unknown };
  if (typeof amount !== "number" || amount <= 0) {
    res.status(400).json({ error: "amount must be a positive number" });
    return; // a real 400, produced after metricsMiddleware already ran
  }
  next();
}

const app = express();
app.use(express.json());
app.use(metricsMiddleware);

app.post("/orders", validateCreateOrder, (req: Request, res: Response) => {
  // Simulate real handler processing time (DB write, etc.).
  const start = Date.now();
  while (Date.now() - start < 40) {
    // busy-wait to stand in for real work
  }
  const orderId = Math.random().toString(36).slice(2);
  res.status(201).json({ orderId });
});

app.get("/metrics", async (_req: Request, res: Response) => {
  res.set("Content-Type", register.contentType);
  res.end(await register.metrics());
});

app.listen(3000);
